150	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
151	// transcript.jsonl format.
152	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
153		base := newTranscriptLine(opts)
154	
155		// Pass 1: parse all lines into intermediate entries.
156		entries, err := parseJSONLEntries(content)
157		if err != nil {
158			return nil, err
159		}
160	
161		// Pass 2: merge and emit.
162		var result []byte
163		for i := 0; i < len(entries); i++ {
164			e := entries[i]
165	
166			switch e.kind {
167			case transcript.TypeAssistant:
168				// Merge consecutive assistant entries with the same message ID.
169				merged := e
170				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
171					i++
172					merged = mergeAssistantEntries(merged, entries[i])
173				}
174	
175				// Look ahead for user tool_result entries to inline.
176				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
177					userEntry := entries[i+1]
178					merged = inlineToolResults(merged, userEntry)
179					i++ // consume the user tool_result entry
180	
181					// If the consumed user entry also had text or image content, emit it
182					// as a separate user line after the assistant.
183					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
184						emitAssistant(&result, base, merged)
185						emitUser(&result, base, userEntry)
186						continue
187					}
188				}
189	
190				if isEmptyContentArray(merged.content) {
191					continue
192				}
193	
194				emitAssistant(&result, base, merged)
195	
196			case transcript.TypeUser:
197				// User entries that are purely tool results were already consumed
198				// by the assistant look-ahead above. If we reach one here it was
199				// not preceded by an assistant with a matching tool_use, so emit
200				// it only if it has text or image content.
201				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
202					continue
203				}
204				emitUser(&result, base, e)
205			}
206		}
207	
208		return result, nil
209	}
