249	// appendLine marshals a transcriptLine and appends it (with newline) to result.
250	func appendLine(result *[]byte, line transcriptLine) {
251		b, err := json.Marshal(line)
252		if err != nil {
253			return
254		}
255		*result = append(*result, b...)
256		*result = append(*result, '\n')
257	}
