337	// mergeAssistantEntries combines two assistant entries with the same message ID.
338	// Content arrays are concatenated; the later timestamp and token counts win
339	// (streaming fragments report cumulative usage, so the last fragment is final).
340	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
341		merged := a
342		merged.ts = b.ts
343		if b.inputTokens > 0 {
344			merged.inputTokens = b.inputTokens
345		}
346		if b.outputTokens > 0 {
347			merged.outputTokens = b.outputTokens
348		}
349	
350		var aBlocks, bBlocks []json.RawMessage
351		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
352		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
353		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
354		if data, err := json.Marshal(all); err == nil {
355			merged.content = data
356		}
357	
358		return merged
359	}
