217	// geminiContentText extracts the text from a Gemini content field which may
218	// be either a plain JSON string or an array of content parts (each with a
219	// "text" field). Returns the concatenated text or "" if content is absent.
220	func geminiContentText(raw json.RawMessage) string {
221		if len(raw) == 0 {
222			return ""
223		}
224		// Try plain string first.
225		var s string
226		if json.Unmarshal(raw, &s) == nil {
227			return s
228		}
229		// Try array of parts with "text" fields.
230		var parts []struct {
231			Text string `json:"text"`
232		}
233		if json.Unmarshal(raw, &parts) == nil {
234			var sb strings.Builder
235			for _, p := range parts {
236				sb.WriteString(p.Text)
237			}
238			return sb.String()
239		}
240		return ""
241	}
